import React from "react";
import Svg, { Circle, Ellipse, Path } from "react-native-svg";

/**
 * Глифы нижней навигации — набор Solar Linear из макета
 * (Figma 3z0f6dgev4HMwBAHPjTjPo, node 3039:23943).
 *
 * Почему отдельный модуль, а не `icons.tsx`: там реэкспорт Phosphor, а тут
 * ровно пять векторов, срисованных из макета один в один (исходные SVG лежат
 * в `apps/mobile/assets/nav-icons/` — правки вносить сначала туда). Никакой
 * другой экран этими иконками не пользуется: у остального приложения набор
 * Phosphor, и смешивать их в одном экране нельзя.
 *
 * Цвет приходит пропом и раздаётся КАЖДОЙ линии: в выгрузке из Figma он был
 * зашит (#B33036 у активной вкладки, #595959 у остальных), а вкладка меняет
 * цвет при переключении.
 *
 * У «Мои брони» (School / Notebook) обложка приехала не линией, а уже
 * развёрнутым в заливку контуром — поэтому там `fill={color}`, а не
 * `stroke={color}`; линия та же самая, просто выгружена другой.
 */
export interface NavIconProps {
  /** Сторона квадрата глифа. В макете 24. */
  size?: number;
  /** Цвет линии. Обязателен: у иконки нет «цвета по умолчанию». */
  color: string;
}

